import manifest from "./manifest.json" with { type: "json" };

/**
 * Demo key → source file, relative to this directory.
 *
 * Server-safe: no component imports, so route handlers, build scripts and
 * the llms text generator can read demo metadata without pulling every demo
 * component into their module graph. Rendering goes through `DemoLoader`
 * in `./loader.tsx`. `manifest.json` is generated by scripts/gen-demos.mjs.
 */
export const demoFiles: Readonly<Record<string, string>> = manifest;

export function getDemoFile(name: string): string | undefined {
  return Object.hasOwn(demoFiles, name) ? demoFiles[name] : undefined;
}
